}
local s = table.concat(P)
local A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local T = {}
for i = 1, 64 do T[A:byte(i)] = i - 1 end
local out, n, buf, bits = {}, 0, 0, 0
for i = 1, #s do
	local c = T[s:byte(i)]
	if c then
		buf = buf * 64 + c
		bits = bits + 6
		if bits >= 8 then
			bits = bits - 8
			local p = 2 ^ bits
			local b = math.floor(buf / p)
			buf = buf % p
			n = n + 1
			out[n] = string.char(bit32.bxor(b, K[(n - 1) % #K + 1], n % 256))
		end
	end
end
local f, e = (loadstring or load)(table.concat(out), "=LUNAR")
if not f then error(e) end
return f(...)

